<div x-show="historyModalOpen" x-cloak class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-[1px]"><div  class="flex max-h-[85vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-xl dark:border-slate-700 dark:bg-slate-900"><div class="flex items-center justify-between border-b border-gray-100 px-6 py-5 dark:border-slate-800"><div><span class="text-xs font-semibold uppercase tracking-wider text-gray-400">SMS Center</span><h2 class="text-xl font-bold text-gray-900 dark:text-white">Broadcast History</h2></div><div class="flex items-center gap-3"><span class="rounded-full bg-gray-100 px-3 py-1 text-xs font-medium text-gray-600" x-text="broadcastHistory.length + ' broadcasts'"></span><button type="button" @click="historyModalOpen = false" aria-label="Close broadcast history" class="text-gray-400 hover:text-gray-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" d="M6 6l12 12M18 6 6 18"/></svg></button></div></div><div class="space-y-4 overflow-y-auto p-6"><template x-for="(item, index) in broadcastHistory" :key="index"><article class="space-y-3 rounded-2xl border border-gray-200 bg-white p-5 dark:border-slate-700 dark:bg-slate-800"><div class="flex items-center justify-between gap-3 text-xs"><div class="font-bold text-gray-900 dark:text-white"><span x-text="item.barangay"></span><span class="mx-1 font-normal text-gray-400">•</span><span class="font-normal text-gray-500" x-text="item.status"></span></div><span class="shrink-0 text-gray-400" x-text="item.date"></span></div><p class="text-sm leading-relaxed text-gray-600 dark:text-slate-300" x-text="item.message"></p><div class="flex items-center justify-between pt-1"><div class="flex items-center gap-2"><span class="inline-flex items-center gap-1 rounded-lg bg-green-100 px-2.5 py-1 text-xs font-semibold text-green-700"><svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m5 12 4 4L19 6"/></svg><span x-text="item.sentCount + ' Sent'"></span></span><span x-show="item.failedCount > 0" class="inline-flex items-center gap-1 rounded-lg bg-red-100 px-2.5 py-1 text-xs font-semibold text-red-600"><svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" d="M12 8v4m0 4h.01M10.3 3.5 2.5 18a2 2 0 0 0 1.7 3h15.6a2 2 0 0 0 1.7-3l-7.8-14.5a2 2 0 0 0-3.4 0Z"/></svg><span x-text="item.failedCount + ' Failed'"></span></span></div><button x-show="item.failedCount > 0" type="button" @click="item.showFailed = !item.showFailed" class="inline-flex cursor-pointer items-center gap-1 text-xs font-medium text-gray-600 hover:text-gray-900"><span x-text="item.showFailed ? 'Hide failed' : 'View failed'"></span><svg class="h-4 w-4 transition-transform" :class="item.showFailed ? 'rotate-180' : ''" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m6 9 6 6 6-6"/></svg></button></div><div x-show="item.showFailed" x-collapse class="mt-3 border-t border-gray-100 pt-3 dark:border-slate-700"><div class="mb-2 text-[11px] font-semibold uppercase tracking-wider text-gray-400">Failed Deliveries</div><template x-for="recipient in item.failedRecipients" :key="recipient.phone"><div class="flex items-center justify-between gap-3"><div><div class="text-sm font-bold text-gray-800 dark:text-white" x-text="recipient.name"></div><div class="font-mono text-xs text-gray-500" x-text="recipient.phone"></div></div><span class="inline-flex items-center gap-1 rounded-lg bg-red-50 px-2.5 py-1 text-xs font-semibold text-red-600"><svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" d="M6 6l12 12M18 6 6 18"/></svg>Failed</span></div></template></div></article></template></div></div></div>
